<script setup lang="ts">
import { reactive } from 'vue';
import { ElButton, ElInput, ElInputNumber, ElMessage } from 'element-plus';
import { projectApi } from '#/api/creative-video';
import type { Project } from '#/api/creative-video';
const props=defineProps<{initialName:string}>();const emit=defineEmits<{created:[Project];cancel:[]}>();
const form=reactive({name:props.initialName,productName:'',description:'',url:'',audience:'交给 AI 判断',market:'中国大陆',channels:['抖音','微信视频号'],duration:30,aspect:'9:16',styles:['交给 AI'],licensed:false});
function submit(){try{const url=new URL(form.url);if(!['http:','https:'].includes(url.protocol))throw Error('请输入 HTTP(S) 网址');if(!form.licensed)throw Error('请确认素材授权');if(!form.channels.length)throw Error('请选择传播渠道');const project={...projectApi.create(form.name),...form};emit('created',project);}catch(e){ElMessage.warning((e as Error).message);}}
</script>
<template><section class="wizard"><h2>新建创意项目</h2><p>先确定目标与规格。120 秒影片的适配建议将在创意确定后提供。</p><label>项目名称（必填，最多 100 字）<ElInput v-model="form.name" :maxlength="100"/></label><label>产品名称<ElInput v-model="form.productName"/></label><label>产品简介<ElInput v-model="form.description" type="textarea"/></label><label>产品网址<ElInput v-model="form.url" placeholder="https://your-product.com"/></label><label>目标市场<select v-model="form.market"><option>中国大陆</option><option>全球</option></select></label><label>目标受众与广告诉求<ElInput v-model="form.audience"/></label><div>传播渠道<label v-for="c in ['抖音','微信视频号','B站','TikTok','官网','销售介绍']" :key="c" class="inline"><input v-model="form.channels" type="checkbox" :value="c"/>{{ c }}</label></div><label>目标秒数（15/30/45/60/90/120 或自定义）<ElInputNumber v-model="form.duration" :min="5" :max="300"/></label><label>画面比例<select v-model="form.aspect"><option>9:16</option><option>16:9</option><option>1:1</option></select></label><label>语言：简体中文</label><div>风格偏好<label v-for="s in ['交给 AI','反常规','搞笑','情绪','创意动画','电影感','3D']" :key="s" class="inline"><input v-model="form.styles" type="checkbox" :value="s"/>{{ s }}</label></div><label><input v-model="form.licensed" type="checkbox"/> 我有权使用所提供的资料、素材和演示环境</label><ElButton type="primary" @click="submit">创建并进入资料采集</ElButton><ElButton @click="emit('cancel')">取消</ElButton></section></template>
<style scoped>.wizard{max-width:900px;background:var(--el-bg-color);padding:32px;border-radius:14px;margin:24px 0}h2{font-size:24px;font-weight:700}label{display:block;margin:18px 0}.inline{display:inline-block;margin:12px}p{color:#8590a1;margin:14px 0}select{margin-left:12px}</style>
